mapper.select:
select log.FUNCTION_ID functionId , log.PORTFOLIO_ID portfolioId , log.IND_ID indId , log.LOG_LVL logLvl , log.MESSAGE message , log.LOG_TIME logTime , m.IND_TYPE indType , m.IND_NAME indName , log.CREATE_TIME createTime , case when n.PORTFOLIO_LEVEL='02' then E.PTL_BAG_NAME else p.PORTFOLIO_NAME end portfolioName from RSK_ISUP_LOG log left join RSK_PORTFOLIO_INDICATOR n on log.IND_ID=n.IND_ID and log.PORTFOLIO_ID=n.PORTFOLIO_ID left join RSK_ISUP_INDICATOR m on log.IND_ID=m.IND_ID left join PTL_PORTFOLIO p on log.PORTFOLIO_ID=p.PORTFOLIO_ID LEFT JOIN RSK_PORTFOLIO_PACKAGE E ON E.PTL_BAG_ID =LOG.PORTFOLIO_ID
( P.PORTFOLIO_NAME LIKE CONCAT_ws('', '%',#{portfolioName}, '%') OR E.PTL_BAG_NAME LIKE concat_ws('','%',#{portfolioName},'%') )
AND DATE_FORMAT(log.LOG_TIME,'%Y-%m-%d') >= #{stDate}
and DATE_FORMAT(log.LOG_TIME,'%Y-%m-%d') <= #{edDate}
and log.LOG_LVL = #{logLvl}
and log.FUNCTION_ID = #{functionId}
order by log.CREATE_TIME desc
